import re; from pathlib import Path  # AC-runtime.20.5
class TestConfigContract:
    def test_small_model_format(self): 'AC-runtime.18.1'; from src.config import settings; assert settings.ai_provider == 'zai'; assert settings.small_model.startswith('glm-'), f'Invalid model provider: {settings.small_model}. Expected GLM model ID'; assert re.match('^glm-[\\d.a-z-]+', settings.small_model), f'Invalid model format: {settings.small_model}. Expected pattern: glm-<version>'
    def test_config_sync_with_env_example(self):
        'AC-runtime.18.2'; from src.config import settings; env_example_path = Path(__file__).parent.parent.parent.parent.parent / '.env.example'; env_example = env_example_path.read_text()
        match = re.search('^SMALL_MODEL=(.+)$', env_example, re.MULTILINE); assert match, '.env.example missing SMALL_MODEL definition'; expected = match.group(1).strip(); assert settings.small_model == expected, f'Config default mismatch:\n  config.py:        {settings.small_model}\n  .env.example:     {expected}\nPlease update config.py default to match .env.example'
    def test_base_currency_format(self): 'AC-runtime.18.3'; from src.config import settings; assert settings.base_currency.isalpha(), f'Invalid currency code: {settings.base_currency}. Must be alphabetic (ISO 4217)'; assert len(settings.base_currency) == 3, f'Invalid currency code: {settings.base_currency}. Must be 3 characters (ISO 4217)'; assert settings.base_currency.isupper(), f'Invalid currency code: {settings.base_currency}. Must be uppercase (ISO 4217)'
    def test_s3_bucket_format(self): 'AC-runtime.18.4'; from src.config import settings; assert settings.s3_bucket.islower() or settings.s3_bucket.replace('-', '').islower(), f'Invalid S3 bucket name: {settings.s3_bucket}. Must be lowercase'; assert 3 <= len(settings.s3_bucket) <= 63, f'Invalid S3 bucket name: {settings.s3_bucket}. Must be 3-63 characters'; assert re.match('^[a-z0-9][a-z0-9-]*[a-z0-9]$', settings.s3_bucket), f'Invalid S3 bucket name: {settings.s3_bucket}. Must contain only lowercase letters, numbers, and hyphens'
    def test_jwt_algorithm_allowed(self): 'AC-runtime.18.5'; from src.config import settings; allowed_algorithms = {'HS256', 'RS256'}; assert settings.jwt_algorithm in allowed_algorithms, f'Insecure JWT algorithm: {settings.jwt_algorithm}. Allowed: {allowed_algorithms}'
    def test_database_url_format(self): 'AC-runtime.18.6'; from src.config import settings; assert 'postgresql+asyncpg://' in settings.database_url or 'sqlite' in settings.database_url, f'Invalid database URL: {settings.database_url}. Expected postgresql+asyncpg:// or sqlite://'
    def test_db_pool_size_config_default(self, monkeypatch): 'AC-runtime.20.1'; monkeypatch.delenv('DB_POOL_SIZE', raising=False); from src.config import Settings; s = Settings(); assert hasattr(s, 'db_pool_size'); assert s.db_pool_size == 5
    def test_db_pool_max_overflow_config_default(self, monkeypatch): 'AC-runtime.20.2'; monkeypatch.delenv('DB_POOL_MAX_OVERFLOW', raising=False); from src.config import Settings; s = Settings(); assert hasattr(s, 'db_pool_max_overflow'); assert s.db_pool_max_overflow == 10
    def test_db_pool_config_valid_range(self, monkeypatch): 'AC-runtime.20.3'; monkeypatch.delenv('DB_POOL_SIZE', raising=False); monkeypatch.delenv('DB_POOL_MAX_OVERFLOW', raising=False); from src.config import Settings; s = Settings(); assert s.db_pool_size >= 1; assert s.db_pool_max_overflow >= 0
    def test_db_pool_size_env_override(self, monkeypatch): 'AC-runtime.20.4'; monkeypatch.setenv('DB_POOL_SIZE', '20'); from src.config import Settings; s = Settings(); assert s.db_pool_size == 20; monkeypatch.setenv('DB_POOL_MAX_OVERFLOW', '25'); from src.config import Settings; s = Settings(); assert s.db_pool_max_overflow == 25
    def test_model_roles_default_to_the_sdk_and_use_the_code_source_class(self, monkeypatch): [monkeypatch.delenv(name, raising=False) for name in ('LARGE_MODEL', 'SMALL_MODEL', 'MULTIMODAL_MODEL')]; from infra2_sdk.runtime.llm import LlmSettings; from src.config import ENV_SOURCE_CLASSES, Settings; s = Settings(_env_file=None); sdk = LlmSettings(); assert (s.large_model, s.small_model, s.multimodal_model) == (sdk.role_model('large'), sdk.role_model('small'), sdk.role_model('multimodal')); assert all((field not in ENV_SOURCE_CLASSES for field in ('large_model', 'small_model', 'multimodal_model')))
    def test_empty_next_public_app_url_and_otel_resource_attributes_normalize(self, monkeypatch): monkeypatch.setenv('NEXT_PUBLIC_APP_URL', ''); monkeypatch.setenv('OTEL_RESOURCE_ATTRIBUTES', ''); from src.config import Settings; s = Settings(_env_file=None); assert s.next_public_app_url == 'http://localhost:3000'; assert s.otel_resource_attributes is None
